import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const root = new Group();

  // Create a timeline to track local animations for clean entry and idle vibes
  const tl = gsap.timeline();

  // 1. STAGE BACKDROP (Z = -2.5) — Vertical engineered gradient
  const bgGeom = new PlaneGeometry(8, 6);
  const bgMat = new MeshBasicNodeMaterial();

  // Custom TSL gradient for the background (Engineered surface / dark stage design)
  const inkColor = vec3(new Color('#16161d').r, new Color('#16161d').g, new Color('#16161d').b);
  const surfaceColor = vec3(new Color('#0b0b10').r, new Color('#0b0b10').g, new Color('#0b0b10').b);
  const accentColor = vec3(new Color('#ff2a38').r, new Color('#ff2a38').g, new Color('#ff2a38').b);

  const vUv = uv();
  // Build backdrop shader with top-to-bottom dark gradient + subtle signal red spill at the bottom
  const bgGradient = mix(surfaceColor, inkColor, vUv.y);
  const redSpill = smoothstep(0.0, 0.4, 1.0, vUv.y.oneMinus()).mul(accentColor).mul(0.12);
  bgMat.colorNode = bgGradient.add(redSpill);

  const backdrop = new Mesh(bgGeom, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // 2. HERO PRICING CARD (Z = 0)
  // Dimensions for "Pricing card 2"
  const cardGeom = new PlaneGeometry(3.0, 4.2);
  const cardMat = new MeshStandardNodeMaterial({
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    transparent: true,
    opacity: 0.98
  });

  // Load the brushed metal texture safely
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  // TSL base configuration to tint the card and give it an engineered tech-border
  const cardBaseTint = vec3(new Color('#0b0b10').r, new Color('#0b0b10').g, new Color('#0b0b10').b);
  const paperTint = vec3(new Color('#e8ecf2').r, new Color('#e8ecf2').g, new Color('#e8ecf2').b);

  // Create an elegant framing border node
  const borderX = smoothstep(0.0, 0.015, vUv.x).mul(smoothstep(0.0, 0.015, vUv.x.oneMinus()));
  const borderY = smoothstep(0.0, 0.011, vUv.y).mul(smoothstep(0.0, 0.011, vUv.y.oneMinus()));
  const borderFactor = borderX.mul(borderY);

  // Inner fill content vs subtle outline
  const cardBodyColor = mix(accentColor.mul(0.15), cardBaseTint, borderFactor);
  cardMat.colorNode = cardBodyColor;

  const card = new Mesh(cardGeom, cardMat);
  card.position.set(0, -0.1, 0);
  root.add(card);

  // 3. INTERNAL STAGING LIGHTING (Local product-shot environment)
  // Direct light ceiling compliance (W-PCP §9.1: Summed direct direct <=2.0)
  const keyLight = new DirectionalLight('#e8ecf2', 1.0);
  keyLight.position.set(3, 4, 3);
  root.add(keyLight);

  // Back / Rim Light capturing the red accents of Nova Atelier
  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-3, -2, -1);
  root.add(rimLight);

  // 4. MOTION & TRANSITION
  // Smooth rise-in entrance on load
  gsap.fromTo(
    card.position,
    { y: -0.6, z: -0.1 },
    { y: -0.1, z: 0, duration: 1.2, ease: 'power4.out', delay: 0.1 }
  );

  // Clean-up hooks
  root.userData.cleanup = () => {
    tl.kill();
    bgGeom.dispose();
    bgMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
  };

  return root;
}
